Method.Source:
    /// <summary>
    /// Form datasource Active method to enable/disable Advance calculation field based Modeule category - header/Line auto charges
    /// </summary>
    int active()
    {
        FormCheckBoxControl AdvanceCalculationControl;
        int ret = next active();

        AdvanceCalculationControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoTable_METAdvancedCalculation)) as FormCheckBoxControl;
        MarkupAutoTable markupAutoTable = this.cursor();//this.formRun().dataSource().cursor();
        //If the current record is HEader auto charges, then, Advance calculation field is visible
        if(markupAutoTable.moduleCategory == HeadingLine::Heading)
        {
            AdvanceCalculationControl.visible(true);
        }
        else
        {
            AdvanceCalculationControl.visible(false);
        }
        return ret;
    }
